// @tencent/qimei-node-unified — self-contained variant.
// All native artifacts live next to this file; nothing is resolved via
// optionalDependencies, so this package installs cleanly on any platform
// (Linux included). Only actual instantiation requires a supported platform.

const path = require('path');

const NULL_SIGN = '\u0000\u0000\u0000\u0000\u0000\u0000';

function loadNative(nativeBasePath = __dirname) {
    const triple = `${process.platform}-${process.arch}`;
    const supported = new Set(['darwin-arm64', 'darwin-x64', 'win32-x64']);
    if (!supported.has(triple)) {
        throw new Error(
            `@tencent/qimei-node-unified: platform ${triple} is not supported. `
            + 'Supported: darwin-arm64, darwin-x64, win32-x64.'
        );
    }
    // eslint-disable-next-line import/no-dynamic-require, global-require
    return require(path.join(nativeBasePath, `qimei.${triple}.node`));
}

async function retry(fn, max = 5, delayMs = 500) {
    for (let i = 0; i < max; i += 1) {
        // eslint-disable-next-line no-await-in-loop
        const v = await fn(i);
        if (v) return v;
        // eslint-disable-next-line no-await-in-loop
        await new Promise((r) => setTimeout(r, delayMs));
    }
    return '';
}

class QimeiSdk {
    constructor(options) {
        const { appKey, appVersion = '', dllPath = '', bindingsDir = __dirname } = options || {};
        if (!appKey) throw new Error('appKey is required');
        this.appKey = appKey;
        this.appVersion = appVersion;

        const native = loadNative(bindingsDir);
        // On Windows, if no explicit dllPath is given, fall back to the bundled qimei.dll
        // that ships alongside this file.
        const effectiveDllPath = process.platform === 'win32'
            ? (dllPath || path.join(bindingsDir, 'qimei.dll'))
            : '';
        this._ins = new native.QimeiServiceWrapper(appKey, appVersion, effectiveDllPath || null);
        this._ins.start();
    }

    getVersion() {
        return this._ins.sdkVersion();
    }

    async getQimei36() {
        return retry(() => {
            const q = this._ins.getQimei();
            const v = q && q.q36 ? String(q.q36) : '';
            if (v && !v.startsWith(NULL_SIGN)) return v;
            return '';
        });
    }

    async getQimei32() {
        if (process.platform !== 'win32') return '';
        return retry(() => {
            const q = this._ins.getQimei();
            const v = q && q.q32 ? String(q.q32) : '';
            if (v && !v.startsWith(NULL_SIGN)) return v;
            return '';
        });
    }

    async getUskey(busId, busInfos = '') {
        if (!busId) throw new Error('busId is required');
        if (process.platform === 'win32' && !this.appVersion) {
            throw new Error('appVersion is required for uskey on Windows');
        }
        const infos = busInfos && typeof busInfos === 'object'
            ? new URLSearchParams(busInfos).toString()
            : (busInfos || '');
        const q36 = await this.getQimei36();
        if (!q36) throw new Error('failed to get qimei36, cannot get uskey');
        return retry(() => {
            try {
                const uskey = this._ins.getUskey(String(busId), q36, infos);
                if (uskey && uskey !== '-1') return uskey;
            } catch (e) {
                console.error('getUskey error:', e);
            }
            return '';
        });
    }
}

module.exports = QimeiSdk;
